async Task<Data> LoadAsync(CancellationToken callerCt)
{
    using var cts = CancellationTokenSource.CreateLinkedTokenSource(callerCt);
    cts.CancelAfter(TimeSpan.FromSeconds(5));
    try
    {
        return await FetchAsync(cts.Token);
    }
    catch (OperationCanceledException) when (!callerCt.IsCancellationRequested)
    {
        throw new TimeoutException("The server has been silent for over 5 s");
    }
}
